// Package registry is the generation source of the IANA-derived TLS
// supported-group data (PQ-18): it loads the committed CSV snapshot under
// tests/fixtures/iana/ — regenerated by scripts/regen_tls_parameters.sh from
// https://www.iana.org/assignments/tls-parameters/tls-parameters-8.csv —
// into lookup form. The snapshot is versioned data, never hand-edited
// (AGENTS.md, registry rule): codepoint drift is fixed by regenerating,
// not by surveying.
package registry

import (
	"bufio"
	"encoding/csv"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// GroupEntry is one row of the IANA TLS Supported Groups table
// (tls-parameters-8.csv): codepoint, RFC-mandated name, transport
// applicability and IANA "Recommended" state.
type GroupEntry struct {
	Value       uint32
	Name        string
	DTLSOK      bool
	Recommended bool
	Reference   string
}

// Load parses the IANA tls-parameters-8.csv export into codepoint-indexed
// entries. Skipped lines: '#' comments, blank lines, the structural
// "Value,..." header line(s), and IANA block-notation range rows ("N-M" —
// the Unassigned and private-use swathes carry no single-codepoint
// semantics). Quoted fields hold embedded commas and quotes; a malformed
// row — non-numeric value, fewer than five fields, unknown DTLS-OK or
// Recommended flag — aborts the load with the physical line number. The
// snapshot is one record per physical line; IANA's trailing Comment
// column beyond the five semantic columns is tolerated and ignored.
func Load(r io.Reader) (map[uint32]GroupEntry, error) {
	entries := make(map[uint32]GroupEntry)
	sc := bufio.NewScanner(r)
	lineNo := 0
	for sc.Scan() {
		lineNo++
		if err := parseLine(sc.Text(), lineNo, entries); err != nil {
			return nil, err
		}
	}
	if err := sc.Err(); err != nil {
		return nil, fmt.Errorf("registry: scan: %w", err)
	}
	return entries, nil
}

// parseLine processes one physical CSV line into entries.
func parseLine(line string, lineNo int, entries map[uint32]GroupEntry) error {
	line = strings.TrimSpace(line)
	if line == "" || strings.HasPrefix(line, "#") {
		return nil
	}

	fields, err := splitCSVRow(line)
	if err != nil {
		return fmt.Errorf("registry: line %d: %s", lineNo, err.Error())
	}
	if fields[0] == "Value" { // structural header line, bare or with the Comment column
		return nil
	}
	if len(fields) < 5 {
		return fmt.Errorf("registry: line %d: malformed row: got %d fields, need at least 5", lineNo, len(fields))
	}

	value, skip, err := parseValue(fields[0])
	if err != nil {
		return fmt.Errorf("registry: line %d: malformed row: %v", lineNo, err)
	}
	if skip {
		return nil
	}
	dtlsOK, err := parseYN(fields[2], "DTLS-OK", false)
	if err != nil {
		return fmt.Errorf("registry: line %d: malformed row: %v", lineNo, err)
	}
	recommended, err := parseYN(fields[3], "Recommended", true)
	if err != nil {
		return fmt.Errorf("registry: line %d: malformed row: %v", lineNo, err)
	}

	entries[value] = GroupEntry{
		Value:       value,
		Name:        fields[1],
		DTLSOK:      dtlsOK,
		Recommended: recommended,
		Reference:   fields[4],
	}
	return nil
}

// splitCSVRow parses one physical line per RFC 4180 (quoted fields; the
// snapshot format is one record per line, so embedded newlines are not in
// scope here).
func splitCSVRow(line string) ([]string, error) {
	return csv.NewReader(strings.NewReader(line)).Read()
}

// parseValue decides a Value column entry: a plain uint32 codepoint, an
// IANA "N-M" block-notation range (skipped, not a load error), or
// malformed.
func parseValue(v string) (uint32, bool, error) {
	if lo, hi, isRange := strings.Cut(v, "-"); isRange {
		_, errLo := strconv.ParseUint(lo, 10, 64)
		_, errHi := strconv.ParseUint(hi, 10, 64)
		if errLo == nil && errHi == nil {
			return 0, true, nil
		}
	}
	u, err := strconv.ParseUint(v, 10, 32)
	if err != nil {
		return 0, false, fmt.Errorf("unsupported value %q (want plain uint32 or N-M range)", v)
	}
	return uint32(u), false, nil
}

// parseYN maps an IANA flag column to a bool: "Y" ⇒ true; "N" and the
// empty cell ⇒ false. "D" is IANA's deprecated marker — deprecatedOK
// accepts it (a deprecated group is simply not recommended) and only the
// Recommended column carries it; unknown spellings are malformed rows.
func parseYN(v, column string, deprecatedOK bool) (bool, error) {
	switch v {
	case "Y":
		return true, nil
	case "N", "":
		return false, nil
	case "D":
		if deprecatedOK {
			return false, nil
		}
	}
	if deprecatedOK {
		return false, fmt.Errorf("%s %q (want Y, N, D or empty)", column, v)
	}
	return false, fmt.Errorf("%s %q (want Y, N or empty)", column, v)
}

// Lookup returns the registry entry for a supported-group codepoint; a
// miss (including a nil map) yields the zero entry.
func Lookup(m map[uint32]GroupEntry, v uint32) (GroupEntry, bool) {
	entry, ok := m[v]
	return entry, ok
}
